// Extracts a lightweight outline (headings, sample paragraphs, counts)
// from the reference article HTML. Works even if the fetch failed.
const html = $input.first().json.reference_html || '';

function decodeHtml(str = '') {
  return String(str)
    .replace(/&#8211;/g, '-')
    .replace(/&#8217;/g, "'")
    .replace(/&#8220;/g, '"')
    .replace(/&#8221;/g, '"')
    .replace(/&#0?38;/g, '&')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .trim();
}

function stripTags(str = '') {
  return decodeHtml(
    String(str)
      .replace(/<script[\s\S]*?<\/script>/gi, '')
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
  );
}

function firstMatch(regex, source) {
  const match = source.match(regex);
  return match ? match[1] : '';
}

function allMatches(regex, source) {
  const matches = [];
  let match;
  while ((match = regex.exec(source)) !== null) {
    matches.push(match[1]);
  }
  return matches;
}

// Prefer the main article area, fall back to the whole page.
const rawBlock =
  firstMatch(/<article[^>]*>([\s\S]*?)<\/article>/i, html) ||
  firstMatch(/<main[^>]*>([\s\S]*?)<\/main>/i, html) ||
  html;

// Drop scripts and styles so their content is never read as article text.
const block = rawBlock
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '');

const title =
  stripTags(firstMatch(/<h1[^>]*>([\s\S]*?)<\/h1>/i, html)) ||
  decodeHtml(firstMatch(/<meta property="og:title" content="([^"]*)"/i, html)) ||
  stripTags(firstMatch(/<title[^>]*>([\s\S]*?)<\/title>/i, html));

const h2Headings = allMatches(/<h2[^>]*>([\s\S]*?)<\/h2>/gi, block)
  .map(stripTags)
  .filter(Boolean)
  .slice(0, 20);

const h3Headings = allMatches(/<h3[^>]*>([\s\S]*?)<\/h3>/gi, block)
  .map(stripTags)
  .filter(Boolean)
  .slice(0, 30);

const paragraphs = allMatches(/<p[^>]*>([\s\S]*?)<\/p>/gi, block)
  .map(stripTags)
  .filter((p) => p.length > 40);

const wordCount = paragraphs.join(' ').split(/\s+/).filter(Boolean).length;

const reference_structure = {
  available: Boolean(h2Headings.length || paragraphs.length),
  title,
  h2_headings: h2Headings,
  h3_headings: h3Headings,
  sample_paragraphs: paragraphs.slice(0, 3).map((p) => p.slice(0, 400)),
  counts: {
    h2: h2Headings.length,
    h3: h3Headings.length,
    paragraphs: paragraphs.length,
    words: wordCount,
    average_paragraph_words: paragraphs.length
      ? Math.round(wordCount / paragraphs.length)
      : 0,
  },
};

return [{ json: { reference_structure } }];

// Turns the AI outline into clean fields. Always returns exactly one item,
// so the next node can validate it and show a friendly error if needed.
function getRawText(json) {
  if (typeof json.output === 'string') return json.output;
  if (typeof json.text === 'string') return json.text;
  if (Array.isArray(json.content) && typeof json.content[0]?.text === 'string') {
    return json.content[0].text;
  }
  return '';
}

// Takes everything from the first "{" to the last "}".
// This also removes code fences or extra text around the JSON.
function extractJson(text) {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end <= start) return '';
  return text.slice(start, end + 1);
}

const rawText = getRawText($input.first().json).trim();

let plan = {};
let parseError = '';

try {
  plan = JSON.parse(extractJson(rawText));
} catch (error) {
  parseError = error.message;
}

plan = plan.article_plan || plan;

const sections = Array.isArray(plan.sections)
  ? plan.sections
  : Array.isArray(plan.headings)
    ? plan.headings
    : [];

const headings = sections
  .map((section) => ({
    title: String(section.heading || section.h2 || section.title || '').trim(),
    chapter_prompt: String(
      section.chapter_prompt || section.prompt || section.description || ''
    ).trim(),
  }))
  .filter((section) => section.title);

return [
  {
    json: {
      page_title: String(plan.title || '').trim(),
      introduction: String(plan.introduction || plan.introduction_angle || '').trim(),
      headings,
      parse_error: parseError,
    },
  },
];

