// Pairs each generated section with its heading (same order as the split)
// and keeps only a small set of safe HTML tags.
const sections = $('Split Article Sections').all();

function getText(json) {
  if (Array.isArray(json.content) && typeof json.content[0]?.text === 'string') {
    return json.content[0].text;
  }
  if (typeof json.text === 'string') return json.text;
  if (typeof json.output === 'string') return json.output;
  return '';
}

function cleanHtml(text) {
  let html = String(text).replace(/```[a-z]*/gi, '').trim();

  // Remove scripts and styles together with their content.
  html = html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '');

  // Remove every tag that is not on the allowlist.
  html = html.replace(/<(?!\/?(?:p|b|strong|i|em|ul|ol|li)\b)[^>]*>/gi, '');

  // Remove attributes from the allowed tags.
  html = html.replace(/<(p|b|strong|i|em|ul|ol|li)\s[^>]*>/gi, '<$1>');

  // If the model returned plain text, wrap paragraphs in <p> tags.
  if (!/<(p|ul|ol)\b/i.test(html)) {
    html = html
      .split(/\n{2,}/)
      .map((part) => part.trim())
      .filter(Boolean)
      .map((part) => `<p>${part}</p>`)
      .join('');
  }

  return html.replace(/\s*\n\s*/g, ' ').trim();
}

return $input.all().map((item, index) => ({
  json: {
    title: sections[index]?.json.title || '',
    body_html: cleanHtml(getText(item.json)),
  },
}));

// Builds the article body: intro paragraph, then one H2 block per section.
// The post title is not repeated here because WordPress themes print it as the H1.
const escapeHtml = (str = '') =>
  String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const items = $input.all().map((item) => item.json);

const intro = items.find((json) => json.introduction !== undefined) || {};
const sections = items.filter((json) => json.body_html !== undefined);

let html = '';

if (intro.introduction) {
  html += `<p>${escapeHtml(intro.introduction)}</p>`;
}

for (const section of sections) {
  html += `<h2>${escapeHtml(section.title)}</h2>${section.body_html}`;
}

return [
  {
    json: {
      page_title: intro.title || '',
      article_html: html,
    },
  },
];

// Parses the summary, SEO fields and FAQs, then builds the HTML blocks.
const escapeHtml = (str = '') =>
  String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

function getText(json) {
  if (Array.isArray(json.content) && typeof json.content[0]?.text === 'string') {
    return json.content[0].text;
  }
  if (typeof json.text === 'string') return json.text;
  if (typeof json.output === 'string') return json.output;
  return '';
}

function extractJson(text) {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end <= start) return '{}';
  return text.slice(start, end + 1);
}

let data = {};

try {
  data = JSON.parse(extractJson(getText($input.first().json)));
} catch (error) {
  data = {};
}

const summaryHtml = data.quick_summary
  ? `<p><strong>Quick summary:</strong> ${escapeHtml(data.quick_summary)}</p>`
  : '';

let faqHtml = '';
const faqs = Array.isArray(data.faqs) ? data.faqs : [];

if (faqs.length) {
  faqHtml += '<h2>Frequently asked questions</h2>';
  for (const faq of faqs) {
    if (!faq.question || !faq.answer) continue;
    faqHtml += `<h3>${escapeHtml(faq.question)}</h3><p>${escapeHtml(faq.answer)}</p>`;
  }
}

return [
  {
    json: {
      summary_html: summaryHtml,
      faq_html: faqHtml,
      seo_title: String(data.seo_title || '').trim(),
      seo_description: String(data.seo_description || '').trim(),
    },
  },
];

// Combines everything in reading order: quick summary, article, FAQs.
const items = $input.all().map((item) => item.json);

const article = items.find((json) => json.article_html !== undefined) || {};
const extras = items.find((json) => json.faq_html !== undefined) || {};

const contentHtml = [extras.summary_html, article.article_html, extras.faq_html]
  .filter(Boolean)
  .join('');

return [
  {
    json: {
      page_title: article.page_title || '',
      content_html: contentHtml,
      seo_title: extras.seo_title || '',
      seo_description: extras.seo_description || '',
    },
  },
];

